package com.gathin.tvhome;
import android.app.*;
import android.content.*;
import android.graphics.Rect;
import android.view.*;
import android.widget.*;
import java.util.*;
/** Instances and placement share one sampler, including when the original three cards are disabled. */
final class HomeWidgets implements PlacementTarget {
    private final Activity a;private final ViewGroup root;final HomeWidgetStore store;final AndroidWidgetBridge android;final QuoteFeed quotes;private final QuoteParticleLayers particleLayers;private final SystemStatsWidget stats;private final HeaderLayoutController header;private final float density;private final boolean defaultEnabled;
    private final Map<String,HomeWidgetCard> cards=new LinkedHashMap<>();private SystemStatsWidget.Snapshot snapshot;private boolean closed,pending,active;private String preview;private int previewX,previewY;
    private final SystemStatsWidget.Observer observer=s->{snapshot=s;for(HomeWidgetCard card:cards.values())card.update(s);};
    private final android.content.SharedPreferences.OnSharedPreferenceChangeListener listener=(p,key)->{if(key!=null&&(key.startsWith(HomeWidgetStore.P)||key.startsWith("system_stats_")))configure();};
    private final ViewTreeObserver.OnGlobalLayoutListener layout=()->schedule();
    HomeWidgets(Activity a,SystemStatsWidget stats,HeaderLayoutController header){this.a=a;this.stats=stats;this.header=header;root=a.findViewById(R.id.root);store=new HomeWidgetStore(a);android=new AndroidWidgetBridge(a,store);quotes=new QuoteFeed(a,state->{for(HomeWidgetCard c:cards.values())c.quote(state);});density=a.getResources().getDisplayMetrics().density;defaultEnabled=Config.load(a).showStats;particleLayers=new QuoteParticleLayers(root);store.prefs.registerOnSharedPreferenceChangeListener(listener);root.getViewTreeObserver().addOnGlobalLayoutListener(layout);stats.observe(observer);configure();}
    static String sourceName(Context a,String source){if("network".equals(source))return "Netzwerk · LAN + WLAN";if("android".equals(source))return a.getString(R.string.widgets_android);if("quote".equals(source))return a.getString(R.string.quote_title);WidgetSource s=WidgetSource.find(source);return a.getString(s==WidgetSource.CPU?R.string.system_stats_cpu:s==WidgetSource.RAM?R.string.system_stats_ram:s==WidgetSource.STORAGE?R.string.system_stats_storage:R.string.widgets_summary);}
    private int selectedMask(){return (store.prefs.getBoolean(SystemStatsWidget.CPU,true)?1:0)|(store.prefs.getBoolean(SystemStatsWidget.RAM,true)?2:0)|(store.prefs.getBoolean(SystemStatsWidget.STORAGE,true)?4:0)|(store.prefs.getBoolean(SystemStatsWidget.NETWORK,false)?8:0);}
    HomeWidgetStore.Spec spec(String key){if(!HomeWidgetStore.SUMMARY.equals(key))return store.get(key);HomeWidgetStore.Spec s=new HomeWidgetStore.Spec(key,"system");s.width=store.prefs.getInt(HomeWidgetStore.P+"summary_width",430);s.theme=store.prefs.getString(HomeWidgetStore.P+"summary_theme","inherit");s.metricsStyle=SystemInfoStyle.id(store.prefs.getString(HomeWidgetStore.P+"summary_metrics_style","original"));s.network=store.prefs.getBoolean(SystemStatsWidget.NETWORK,false);s.metricsGlass=store.prefs.getBoolean(HomeWidgetStore.P+"summary_metrics_glass",true);s.metricsOpacity=SystemWidgetPolicy.opacity(store.prefs.getInt(HomeWidgetStore.P+"summary_metrics_opacity",45));s.metricsHeight=Math.max(0,store.prefs.getInt(HomeWidgetStore.P+"summary_metrics_height",0));int[] defaults=defaultPoint();s.x=store.prefs.getInt(HomeWidgetStore.P+"summary_x",defaults[0]);s.y=store.prefs.getInt(HomeWidgetStore.P+"summary_y",defaults[1]);s.enabled=store.prefs.getBoolean(SystemStatsWidget.COMBINED,false)&&store.prefs.getBoolean(SystemStatsWidget.ENABLED,defaultEnabled)&&selectedMask()!=0;return s;}
    private int[] defaultPoint(){if(header.view("cpu").getWidth()>0)return header.position("cpu");View left=a.findViewById(R.id.leftBlock);int[] point=new int[2],origin=new int[2];left.getLocationOnScreen(point);root.getLocationOnScreen(origin);return new int[]{store.prefs.getInt(HeaderLayoutController.P+"cpu_x",Math.round((point[0]-origin[0])/density)),store.prefs.getInt(HeaderLayoutController.P+"cpu_y",Math.round((point[1]-origin[1]+left.getHeight())/density)+17)};}
    private void configure(){if(closed)return;List<HomeWidgetStore.Spec> specs=store.all();if(store.prefs.getBoolean(SystemStatsWidget.COMBINED,false))specs.add(0,spec(HomeWidgetStore.SUMMARY));Set<String> keep=new HashSet<>();int demand=0;boolean nativeOn=false,quoteOn=false,quoteImages=false;
        for(HomeWidgetStore.Spec s:specs){keep.add(s.id);WidgetSource source=WidgetSource.find(s.source);int mask=HomeWidgetStore.SUMMARY.equals(s.id)?selectedMask():source==null?0:source.mask|("system".equals(s.source)&&s.network?8:0);HomeWidgetCard card=cards.get(s.id);
            if(card==null||!card.source.equals(s.source)||card.mask!=mask||card.appWidgetId!=s.appWidgetId){if(card!=null){card.close();root.removeView(card);}card=new HomeWidgetCard(a,s,mask,android,particleLayers);cards.put(s.id,card);root.addView(card,new android.widget.FrameLayout.LayoutParams(1,-2));if(snapshot!=null)card.update(snapshot);}
            card.setVisibility(s.enabled?View.VISIBLE:View.GONE);card.style(s);card.active(active&&s.enabled);card.quote(quotes.state());if(s.enabled&&s.quote()){quoteOn=true;quoteImages|="image".equals(s.quoteMode);}if(s.enabled){demand|=mask;nativeOn|=s.android();}
            int w=Math.round(WidgetSource.width(s.source,s.width,Math.max(1,width()))*density),h=(s.android()||s.quote())?Math.round(Math.min(s.height,height())*density):ViewGroup.LayoutParams.WRAP_CONTENT;ViewGroup.LayoutParams lp=card.getLayoutParams();if(lp.width!=w||lp.height!=h){lp.width=w;lp.height=h;card.setLayoutParams(lp);if(s.android())card.nativeSize(Math.round(w/density),Math.min(s.height,height()));}
        }
        for(String id:new ArrayList<>(cards.keySet()))if(!keep.contains(id)){HomeWidgetCard removed=cards.remove(id);removed.close();root.removeView(removed);}
        quotes.configure(active&&quoteOn,quoteImages);stats.demand(demand);if(active&&nativeOn)android.start();else android.stop();schedule();
    }
    private void schedule(){if(closed||pending)return;pending=true;root.post(()->{pending=false;apply();});}
    private void apply(){if(closed||root.getWidth()==0)return;for(String id:cards.keySet()){HomeWidgetStore.Spec s=spec(id);if(s==null)continue;HomeWidgetCard card=cards.get(id);int x=id.equals(preview)?previewX:s.x,y=id.equals(preview)?previewY:s.y;card.setTranslationX(HeaderLayoutPolicy.clamp(x,width(),Math.round(card.getWidth()/density))*density);card.setTranslationY(HeaderLayoutPolicy.clamp(y,height(),Math.round(card.getHeight()/density))*density);}}
    void refreshStyle(){for(String id:cards.keySet()){HomeWidgetStore.Spec s=spec(id);if(s!=null)cards.get(id).style(s);}}
    void show(String id,boolean on){if(HomeWidgetStore.SUMMARY.equals(id)){android.content.SharedPreferences.Editor e=store.prefs.edit().putBoolean(SystemStatsWidget.ENABLED,on);if(on&&selectedMask()==0)e.putBoolean(SystemStatsWidget.CPU,true).putBoolean(SystemStatsWidget.RAM,true).putBoolean(SystemStatsWidget.STORAGE,true);e.apply();}else store.edit(id,s->s.enabled=on);}
    void metricsStyle(String id,String value){if(HomeWidgetStore.SUMMARY.equals(id))store.prefs.edit().putString(HomeWidgetStore.P+"summary_metrics_style",SystemInfoStyle.id(value)).apply();else store.edit(id,s->s.metricsStyle=SystemInfoStyle.id(value));}
    void metricsGlass(String id,boolean on){if(HomeWidgetStore.SUMMARY.equals(id))store.prefs.edit().putBoolean(HomeWidgetStore.P+"summary_metrics_glass",on).apply();else store.edit(id,s->s.metricsGlass=on);}
    void metricsOpacity(String id,int opacity){int value=SystemWidgetPolicy.opacity(opacity);if(HomeWidgetStore.SUMMARY.equals(id))store.prefs.edit().putInt(HomeWidgetStore.P+"summary_metrics_opacity",value).apply();else store.edit(id,s->s.metricsOpacity=value);}
    void automaticHeight(String id){if(HomeWidgetStore.SUMMARY.equals(id))store.prefs.edit().remove(HomeWidgetStore.P+"summary_metrics_height").apply();else store.edit(id,s->s.metricsHeight=0);}
    void network(String id,boolean on){if(HomeWidgetStore.SUMMARY.equals(id))store.prefs.edit().putBoolean(SystemStatsWidget.NETWORK,on).apply();else store.edit(id,s->s.network=on);}
    void theme(String id,String theme){if(HomeWidgetStore.SUMMARY.equals(id))store.prefs.edit().putString(HomeWidgetStore.P+"summary_theme",theme).apply();else store.edit(id,s->s.theme=theme);}
    void resize(String id,int width,int height){if(HomeWidgetStore.SUMMARY.equals(id))store.prefs.edit().putInt(HomeWidgetStore.P+"summary_width",width).putInt(HomeWidgetStore.P+"summary_metrics_height",height).apply();else store.edit(id,s->{s.width=width;if(s.android()||s.quote())s.height=height;else s.metricsHeight=height;});}
    void remove(String id){HomeWidgetStore.Spec s=store.get(id);if(s!=null&&s.android())android.delete(s.appWidgetId);store.remove(id);}
    void start(){active=true;configure();}void stop(){active=false;android.stop();quotes.stop();for(HomeWidgetCard c:cards.values())c.active(false);}
    void close(){closed=true;stop();stats.forget(observer);stats.demand(0);android.close();quotes.close();store.prefs.unregisterOnSharedPreferenceChangeListener(listener);if(root.getViewTreeObserver().isAlive())root.getViewTreeObserver().removeOnGlobalLayoutListener(layout);for(HomeWidgetCard view:cards.values()){view.close();root.removeView(view);}cards.clear();particleLayers.close();}
    public View view(String key){return cards.get(key);}public int width(){return Math.round((root.getWidth()>0?root.getWidth():a.getResources().getDisplayMetrics().widthPixels)/density);}public int height(){return Math.round((root.getHeight()>0?root.getHeight():a.getResources().getDisplayMetrics().heightPixels)/density);}
    public int[] size(String key){View v=view(key);return new int[]{Math.round(v.getWidth()/density),Math.round(v.getHeight()/density)};}
    public Rect bounds(String key){View v=view(key);return new Rect(Math.round(v.getX()),Math.round(v.getY()),Math.round(v.getX()+v.getWidth()),Math.round(v.getY()+v.getHeight()));}
    public int[] position(String key){Rect r=bounds(key);return new int[]{Math.round(r.left/density),Math.round(r.top/density)};}
    public void set(String key,int x,int y){if(HomeWidgetStore.SUMMARY.equals(key))store.prefs.edit().putInt(HomeWidgetStore.P+"summary_x",x).putInt(HomeWidgetStore.P+"summary_y",y).apply();else store.edit(key,s->{s.x=x;s.y=y;});}
    public void preview(String key,int x,int y){preview=key;previewX=x;previewY=y;apply();}public void endPreview(){preview=null;apply();}
    void interact(String key){HomeWidgetCard card=cards.get(key);if(card==null||card.nativeView==null)return;ViewGroup old=(ViewGroup)card.nativeView.getParent();old.removeView(card.nativeView);SettingsSheet p=new SettingsSheet(a,spec(key).title);card.nativeView.setDescendantFocusability(ViewGroup.FOCUS_AFTER_DESCENDANTS);card.nativeView.setOnTouchListener(null);p.content(card.nativeView);p.dialog.setOnDismissListener(d->{((ViewGroup)card.nativeView.getParent()).removeView(card.nativeView);card.nativeView.setDescendantFocusability(ViewGroup.FOCUS_BLOCK_DESCENDANTS);card.nativeView.setOnTouchListener((v,e)->true);old.addView(card.nativeView,new LinearLayout.LayoutParams(-1,0,1));});p.show();card.nativeView.requestFocus();}
}
